                const replacement = props.draft.getSnapshot()
                valueRef.current = replacement
                setValue(replacement)
            }), [props.draft])
            useImperativeHandle(ref, () => ({
                flush: () => {
                    props.onChange?.(valueRef.current)

                    return true
                },
